  if(!transfer||transfer.status!=='settled'||transfer.operation_id!==operation.id||leg.gl_account_id!==owner.gl_account_id||leg.currency!==owner.currency||!row||row.source_id!==operation.id||row.account_id!==bankAccountId||row.currency!==owner.currency||row.status!=='posted'||row.amount_minor!==leg.amount_minor||row.functional_amount_minor!==leg.functional_amount_minor||row.receipt_id!==operation.receipt_id)throw new MoneyError('invalid_treasury_cash_proof','Bank leg, transfer and functional accounting evidence disagree');
