  if(!quote||owner.currency==='USD'||valuation.currency!==owner.currency||valuation.gl_account_id!==owner.gl_account_id||canonical(quoteIdentity(quote))!==canonical(valuation.quote_snapshot)||quote.base_currency!==owner.currency||quote.quote_currency!=='USD'||quote.observed_at>valuation.valued_at||quote.expires_at<=valuation.valued_at||valuation.after_functional_minor!==convertMinor(valuation.native_balance_minor,quote).amount_minor||valuation.adjustment_minor!==valuation.after_functional_minor-valuation.before_functional_minor)throw new MoneyError('invalid_fx_valuation_proof','FX valuation must retain its exact native balance, quoted value and USD adjustment');
